import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Collectors;

public class ParallelStreamHazardDemo {
    public static void processSafely(List<Integer> data) {
        // CORRECT: Stateless, CPU-bound reduction on an ArrayList
        int sum = data.parallelStream()
                      .filter(n -> n % 2 == 0)
                      .mapToInt(Integer::intValue)
                      .sum();

        // DANGEROUS: Mutating external state inside a parallel stream leads to race conditions
        AtomicInteger unsafeCounter = new AtomicInteger(0);
        data.parallelStream().forEach(n -> {
            if (n > 50) {
                unsafeCounter.incrementAndGet(); // Atomic, but execution order/timing is chaotic
            }
        });
    }
}
